lessons.code:
int[] items = { 5, 2, 4 };
int comparisons = 0;
int swaps = 0;
for (int end = items.Length - 1; end > 0; end--)
{
    for (int i = 0; i < end; i++)
    {
        comparisons++;
        if (items[i] > items[i + 1])
        {
            int saved = items[i];
            items[i] = items[i + 1];
            items[i + 1] = saved;
            swaps++;
        }
    }
}
foreach (int item in items) { Console.WriteLine(item); }
Console.WriteLine(comparisons);
Console.WriteLine(swaps);

