int[] items = { 5, 3, 8, 1 };
int comparisons = 0;
int swaps = 0;
for (int i = 0; i < items.Length - 1; i++)
{
    int best = i;
    for (int j = i + 1; j < items.Length; j++)
    {
        comparisons++;
        if (items[j] < items[best]) { best = j; }
    }
    if (best != i)
    {
        int saved = items[i];
        items[i] = items[best];
        items[best] = saved;
        swaps++;
    }
}
foreach (int item in items) { Console.WriteLine(item); }
Console.WriteLine(comparisons);
Console.WriteLine(swaps);

